"""An explicit countable first-order Henkin proof and syntax foundations."""
def register(P, BASES):
    BASES['def-hilbert-fol']=dict(title='本章的一阶 Hilbert 演算',statement='语言可数，含函数、谓词及等号，结构论域非空。用 ¬、→、∀ 为基本符号，其他联结词和 ∃ 按经典等价式定义。公理为所有命题重言式的代入实例、∀xφ→φ[t/x]（代入自由）、∀x(α→β)→(α→∀xβ)（x 不自由出现于 α），以及等号自反与在公式中替换等项的公理。规则为 modus ponens 与全称概括；概括变量不得自由出现于未解除前提。本章理论和被证明结论先取句子，以避开开放前提的一般化限制。⊥ 表示一个固定矛盾句。')
    P('syntax-parse-substitute','foundations/formal-language foundations/structure-interpretation foundations/satisfaction','唯一解析与语义代入引理',r'完全括号化的一阶合式项与公式有唯一语法树，捕获规避的项代入可计算；结构 M 与赋值 s 下，φ[t/x] 的真值等于把 s(x) 改成项 t 的解释后 φ 的真值。','axiom-logic axiom-natural','先按语法树递归处理项，再对公式树归纳；量词步必须先避开变量捕获。',
      r'项由变量、常元及带固定元数的函数符号生成；公式由原子谓词/等号、带括号的联结词及带变量的量词生成。首符号、括号匹配和各符号元数确定根节点与各子串，递归使树唯一。有限字符串扫描及严格更短子串递归给解析算法。',
      r'代入遇变量 x 时换成 t，其他变量不变，函数及联结词对子树递归。遇 ∀y，若 y=x 停止进入该作用域；若 y≠x 却在 t 中自由，先把绑定 y 改为一个不在相关有限变量集中的新变量，再进入。每步处理有限树，改名也由枚举变量找到，故可计算且不捕获自由变量。',
      r'对项结构归纳，可验证代入后项的解释等于修改赋值后的原项解释；原子谓词和等号由此得到公式引理。否定与蕴含按真值表传递归纳结论。',
      r'量词步 y≠x 时，经改名可保证 y 不在 t 中自由，所以改变 s(y) 不影响 t 的解释，两个赋值更新可交换；对所有 y 的值应用归纳结论即得全称式。y=x 时作用域内不代入，与赋值被该量词覆盖一致。完成语义代入引理。$\square$')
    P('fol-soundness','foundations/soundness-completeness foundations/formal-proof foundations/axiomatic-method','一阶 Hilbert 演算的可靠性',r'对本章演算，若句子理论 Γ⊢φ，则每个满足 Γ 的结构都满足 φ。','syntax-parse-substitute def-hilbert-fol','逐行证明每个有限推导步骤都保持在任意 Γ 模型中的真。',
      r'固定任意 Γ 的模型 M。命题重言式代入后在任何原子真值组合下都真。全称实例公理由语义代入引理成立；分配公理在 x 不自由出现于 α 时，可把不依赖 x 的前件固定后检查全称定义。',
      r'等号公理因解释中的相等关系为真正相等而成立，函数与谓词对相等元素解释相同。Γ 的每个前提按假设真。modus ponens 由蕴含真值表保持真。',
      r'全称概括要求被概括变量不自由出现于前提，所以前提在改变该变量赋值时仍真；若此前结论在这些赋值中皆真，就得到全称式。对有限证明长度归纳，最后 φ 在 M 中真。M 任意，可靠性成立。$\square$')
    P('fol-deduction','foundations/natural-deduction foundations/formal-proof','句子前提的演绎定理',r'对句子 α，有 Γ∪{α}⊢β 当且仅当 Γ⊢α→β。','def-hilbert-fol','对使用 α 的证明归纳，把每一行改写成以 α 为前件的蕴含。',
      r'反向直接用 α 和 modus ponens。正向看每行 θ：若 θ 是 Γ 前提或公理，命题重言式 θ→(α→θ) 给 α→θ；若该行是 α，用重言式 α→α。',
      r'若 θ 由 ψ 与 ψ→θ 经 MP 得到，归纳已有 α→ψ、α→(ψ→θ)，使用命题重言式 (α→(ψ→θ))→((α→ψ)→(α→θ))，两次 MP 得到 α→θ。',
      r'若 θ=∀xψ 来自概括，先对 α→ψ 概括得 ∀x(α→ψ)，因 α 为句子，x 不自由出现于 α，可用全称分配公理得到 α→∀xψ。故最后一行也可转换，证明演绎定理。$\square$')
    P('henkin-witness-consistency','foundations/consistency foundations/classification-of-models','新常元见证保持相容性',r'若句子理论 Γ 相容、∃xφ(x) 为旧语言句子且 c 是新常元，则 Γ 加见证公理 ∃xφ(x)→φ(c) 仍相容。','fol-deduction syntax-parse-substitute def-hilbert-fol','若见证公理造成矛盾，旧理论必须同时推出存在句及对所有元素的反例。',
      r'反设加入后可证矛盾。演绎定理及经典命题推理使 Γ⊢¬(∃xφ→φ(c))，所以 Γ⊢∃xφ 且 Γ⊢¬φ(c)。',
      r'后一个证明有限，c 不在 Γ 或 φ 中。先把证明中可能冲突的绑定变量改名，再将所有 c 换成一个新变量 y；按语法和规则逐行检查，公理实例仍是公理实例，MP 保持，概括限制因 Γ 为句子而不受影响。所以 Γ⊢¬φ(y)。',
      r'概括得到 Γ⊢∀y¬φ(y)，即 Γ⊢¬∃xφ，与第一步的存在句矛盾。因此加入见证公理保持相容。无新常元公理时，扩充一个空常元也不破坏相容性，同样的有限证明替换论证即可。$\square$')
    P('henkin-extension','foundations/compactness foundations/classification-of-models','可数相容理论的完备 Henkin 扩张',r'每个可数语言中的相容句子理论 Γ，可在可数扩充语言中扩为相容、演绎封闭、对每句子作决定并含全部存在见证的理论 T。','henkin-witness-consistency fol-deduction axiom-dependent-choice','分层添加见证，再逐句选择一个不导致矛盾的真值；有限证明不能跨过相容链的极限。',
      r'先必要时加一个新常元以保证有闭项。对当前语言的全部存在句枚举，逐个加入新常元见证。每一步按前一引理相容，整条链的并也相容：若有矛盾证明，它只用有限多新公理，已出现在某有限阶段，矛盾。',
      r'添加后出现的新常元又产生新存在句，所以把这个过程对语言层级重复可数次。所得 L_ω 仍可数，每个公式只含有限符号，属于某层，故它的见证会在下一层加入。全体见证理论仍由有限证明论证保持相容。',
      r'枚举 L_ω 所有句子 θ_n。逐次若加入 θ_n 相容就加入，否则加入 ¬θ_n。后者必相容：若两种扩张都不相容，演绎定理给当前理论同时证明 θ_n 与 ¬θ_n，违背原相容。',
      r'取并，再取演绎闭包 T。并的相容性同样由有限证明保证，取闭包不新增可导矛盾。T 对每句子至少取一边，相容性使不能两边都取，且保留全部见证。$\square$')
    P('henkin-model','foundations/classification-of-models foundations/structure-interpretation foundations/satisfaction','Henkin 项模型与真值引理',r'每个相容、完备且有存在见证的 T，具有一个由闭项等价类组成的可数模型 M，并对每个带闭项参数的公式有 M⊨φ 当且仅当 φ∈T。','henkin-extension syntax-parse-substitute def-hilbert-fol','把可证明相等的项识别，原子真值直接由 T 定义，再用见证完成量词步。',
      r'闭项 t,s 按 T⊢t=s 等价。等号公理给自反、对称、传递及函数/谓词替换一致性，所以函数取项运算的等价类、谓词按原子句是否在 T 定义，全部良定义。常元保证论域非空；可数字母表上有限项可枚举，所以模型至多可数。',
      r'项解释按结构归纳恰为该项的等价类，因此等号与谓词原子式满足所述等价。T 完备相容及含全部命题重言式，使否定的成员关系对应“不在 T”，蕴含成员关系对应经典真值表；所以联结词归纳成立。',
      r'若 ∀xφ∈T，全称实例公理使对每个闭项 t 都有 φ(t)∈T，归纳假设给模型中全部元素满足 φ。反之若全称句不在 T，完备性给 ∃x¬φ∈T；见证常元 c 使 ¬φ(c)∈T，从而全称式在模型中假。',
      r'对自由变量赋任一等价类，可选闭项代表并代入；语义代入引理及等号替换使选择无关。由公式归纳得到完整真值引理，特别 T 的每个句子在 M 中真。$\square$')
    P('fol-completeness-compactness','foundations/soundness-completeness foundations/compactness','可数一阶逻辑的完备性与紧致性',r'可数语言中的句子理论满足 Γ⊨φ 当且仅当 Γ⊢φ。若 Γ 的每个有限子集有模型，则 Γ 本身有模型。','henkin-model henkin-extension fol-soundness fol-deduction','不可证明时加入结论否定，构造反模型；紧致性则由有限证明只用有限前提得到。',
      r'若 Γ⊬φ，演绎定理与经典双重否定说明 Γ∪{¬φ} 相容，否则 Γ 可推出 φ。Henkin 扩张及项模型给它的模型，满足 Γ 却不满足 φ，所以 Γ⊭φ。可靠性已给相反方向，于是语义蕴含与可证明性等价。',
      r'若 Γ 每个有限子集可满足而 Γ 不相容，某个有限证明推出矛盾，只用有限多 Γ 前提。可靠性使该有限前提不能有模型，与假设矛盾。因此 Γ 相容，再用模型存在构造得到 Γ 的模型。',
      r'本章明确采用可数签名版本；任意不可数语言的完整版本需要相应超限见证/极大化构造，不能把可数枚举步骤直接称为其证明。结论与算术理论不完备性不冲突，因为这里比较所有模型的逻辑蕴含。$\square$')
    P('dlo-equivalence','foundations/elementary-equivalence foundations/classification-of-models','稠密无端点线序的一阶等价性',r'仅含 < 与等号语言中，任意两个非空稠密无端点线序满足相同一阶句子；更强地，保持次序及相等模式的有限元组对所有公式有相同真值。','syntax-parse-substitute axiom-logic','有限元组的新元素只可能落在某个间隙或等于旧元素，两结构都能实现同样位置。',
      r'原子式只比较元组中的大小及相等，所以次序模式相同就同真。布尔联结词按真值表保留此性质。对公式复杂度作归纳，关键只剩存在量词。',
      r'若第一结构中有见证 a，a 要么等于已有元组元素，要么位于相邻已知元素之间或两端以外。第二结构可选对应相等元素；在真间隙用稠密性选点，在两端以外用无端点性选点。空元组时用论域非空。',
      r'于是扩充元组仍有相同模式，对量词内较简单公式用归纳假设，见证可转移；交换两结构给反向。全称量词由否定存在得到，所以所有公式均转移，空元组给相同句子理论。$\square$')
    P('finite-proof-checking','foundations/formal-proof foundations/proof-assistants','有限证明检查的终止与条件可靠性',r'若形式系统每条推理规则的实例可判定且语义有效，则有限带规则标注的证明树可由总停机检查器验证，接受的结论确为相应前提的语义后果。','fol-soundness axiom-natural','算法只遍历给定有限树；可靠性沿同一树归纳，不需要搜索所有可能证明。',
      r'从叶到根遍历有限树，每节点检查规则名、前提数、变量条件及结论是否匹配该可判定规则；每次局部检查停机，节点总数有限，所以全检查停机。缺失子节点、循环指针等不构成有限树者先以有限图遍历拒绝。',
      r'若接受，叶节点是允许前提或公理。对树高度归纳，子结论在每个前提模型中真，规则语义有效性使父结论也真；故根结论成立。该定理把信任落在规则实现和前提上，不证明任意具体软件没有实现缺陷。$\square$')
    P('oracle-transitivity','foundations/turing-reduction foundations/turing-machine','图灵归约的传递性',r'若 A≤_T B 且 B≤_T C，则 A≤_T C；可判定 A 总有 A≤_T B。','axiom-computation','用第二台带神谕机器逐次替换第一台的每个神谕调用。',
      r'给定输入，模拟判定 A 的 B 神谕机。每当它查询某个 y∈B，调用能借 C 神谕判定 B 的机器，等该子程序停机后将回答送回外层模拟。',
      r'外层原本对该输入有限步终止，因此只提出有限次查询；每个内层查询也按归约假设有限步终止。有限个有限计算组合仍有限，并给同样正确回答，所以得到 A 的 C 神谕判定器。',
      r'若 A 已可判定，直接运行其判定器并忽略神谕就是对任意 B 的归约。这一证明不提供任何多项式时间保证。$\square$')
    P('enumeration-semidecision','foundations/enumerability foundations/turing-machine','可枚举与半可判定的等价',r'允许重复及空输出的程序枚举的语言，恰好是由半判定器接受的语言。','axiom-computation','枚举器可等待目标输出；半判定器可对所有输入交错模拟，避免死循环阻塞。',
      r'若有枚举器，对输入 w 不断模拟并比较每次输出，首次等于 w 就接受；成员最终出现而被接受，非成员永不接受，所以半判定成立。',
      r'若有半判定器 M，按可数字符串枚举 w₁,w₂,…。第 s 阶段把前 s 个模拟各推进一步，某模拟首次接受便输出其字符串。每个已接受输出都是成员；每个成员所需的有限步最终都得到执行，所以必输出。空语言由始终不输出的枚举器覆盖。$\square$')
    P('stlc-substitution','foundations/simple-types foundations/propositions-as-types','简单类型 λ 演算的代入与 β 保型',r'在变量、应用与抽象的标准类型规则下，Γ,x:A⊢t:B 且 Γ⊢s:A，推出 Γ⊢t[s/x]:B；因此 β 约简保持类型。','syntax-parse-substitute axiom-natural','对类型推导作归纳，抽象步先改名避免捕获；β 步随后直接调用代入。',
      r'先证明弱化：在环境增加未冲突声明后，原类型推导逐节点仍合法，按推导高度归纳即可。对代入推导归纳，若 t=x，直接用 s 的给定类型；其他变量沿用 Γ 声明。',
      r'应用 t=uv 时，由归纳假设 u[s/x] 保持箭头类型、v[s/x] 保持输入类型，再应用类型规则。抽象 λy:C.u 时先改名使 y≠x 且 y 不在 s 自由变量中；弱化使 s 在 Γ,y:C 下仍有类型 A，归纳得到代入后的体具有原类型，再重建抽象。',
      r'若 (λx:A.t)s:B 为良类型，规则反演给出体 t:B 与参数 s:A，代入引理使 β 结果 t[s/x]:B。发生在子项的约简则按应用或抽象的上下文规则重建推导，故全部一步 β 约简保型。反复有限步同理，但不由此单独推出所有约简终止。$\square$')
    P('list-induction-length','foundations/inductive-types foundations/dependent-types','列表拼接的长度定理与非空向量的头元素',r'归纳列表的拼接满足 len(xs++ys)=len(xs)+len(ys)。若 Vec(A,n) 的构造子仅 nil:Vec(A,0)、cons:A×Vec(A,n)→Vec(A,n+1)，则 head 可总定义于 Vec(A,n+1)。','axiom-natural','列表性质按构造子归纳；长度索引排除空构造子。',
      r'拼接按 []++ys=ys、(a::xs)++ys=a::(xs++ys) 递归。空列表时长度式为 len ys=0+len ys；cons 情形，长度为 1+len(xs++ys)，用归纳假设得 1+len xs+len ys，正是右边。',
      r'非空索引 n+1 不可能等于零，因为自然数零与后继构造子不交。因此 Vec(A,n+1) 的值不可能由 nil 产生，只能为某 cons(a,v)。定义 head(cons(a,v))=a，所有允许构造情形均覆盖且返回 A，故为所列输入类型上的总函数。$\square$')
    P('adjoint-unique','foundations/adjunction foundations/limits-colimits','左伴随在自然同构意义下唯一',r'若 F,F′ 都满足对同一 G 的左伴随泛性质，则存在唯一与两组单位相容的自然同构 F⇒F′。','universal-unique def-category','每个自由对象的泛性质给正反态射，唯一性使其互逆并迫使自然性。',
      r'用单位 η_X:X→GFX、η′_X:X→GF′X 表达伴随：任意 X→GY 都唯一分解为 G(u)η_X。对 η′_X 应用 F 的泛性质给 u_X:FX→F′X，满足 G(u_X)η_X=η′_X；反向同理给 v_X。',
      r'两次代入后，G(v_Xu_X)η_X=η_X，恒等也满足；唯一性迫使 v_Xu_X=id，另方向同样，所以各分量同构。',
      r'对 f:X→Y，F′f·u_X 与 u_Y·Ff 在作用 G 后再接 η_X 都等于 η′_Y f。单位的自然性来自伴随 Hom 对应的自然性（或作为单位泛性质的相容条件），所以唯一性使两态射相等，得到自然同构。每分量的唯一性给整变换唯一。$\square$')
    P('transfinite-induction','foundations/ordinals foundations/ordinal-analysis','良序上的超限归纳原理',r'若 (W,<) 为良序，性质 P 满足每个 x 在全部严格前驱满足 P 时也满足 P，则 W 中所有元素满足 P。','axiom-set','非空反例集必有最小反例，其前驱已经全部正确。',
      r'反设反例集 C={x∈W:¬P(x)} 非空。良序定义给其最小元素 c。任意 y<c 若不满足 P 就是更小反例，与 c 最小矛盾，所以全部前驱都满足。',
      r'由归纳假设条件，c 也满足 P，矛盾。因此反例集空。本定理把良序性当作明确前提；不能据此未经证明就断言任意序数记号系统在某个弱算术理论中可证良基。$\square$')
